import sys

def main() -> None:
    count = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            x = int(line)
        except ValueError:
            continue
        if x < 0:
            count += 1
    print(count)

if __name__ == "__main__":
    main()

