    if (scanf("%d", &n) != 1) return 0;
    long long profit = 0, loss = 0, neutral = 0;
    for (int i = 0; i < n; i++) {
        int val;
        if (scanf("%d", &val) != 1) return 0;
        if (val > 0) profit++;
        else if (val < 0) loss++;
        else neutral++;
    }
    printf("%lld %lld %lld\n", profit, loss, neutral);
    return 0;
}

